#include <vector>
#include <unordered_map>
#include <unordered_set>
#include <queue>
#include <algorithm>

class Solution {
public:
    int minJumps(std::vector<int>& nums) {
        int n = nums.size();
        if (n <= 1) return 0;

        int max_val = *std::max_element(nums.begin(), nums.end());
        std::vector<int> spf(max_val + 1);
        for (int i = 0; i <= max_val; ++i) spf[i] = i;
        for (int i = 2; i * i <= max_val; ++i) {
            if (spf[i] == i) {
                for (int j = i * i; j <= max_val; j += i) {
                    if (spf[j] == j) spf[j] = i;
                }
            }
        }

        auto get_primes = [&](int x) {
            std::vector<int> res;
            while (x > 1) {
                int p = spf[x];
                res.push_back(p);
                while (x % p == 0) x /= p;
            }
            return res;
        };

        std::unordered_map<int, std::vector<int>> prime_to_indices;
        for (int i = 0; i < n; ++i) {
            for (int p : get_primes(nums[i])) {
                prime_to_indices[p].push_back(i);
            }
        }

        std::vector<bool> visited_indices(n, false);
        std::unordered_set<int> visited_primes;
        std::queue<std::pair<int, int>> qu;

        visited_indices[0] = true;
        qu.push({0, 0});

        while (!qu.empty()) {
            auto [curr, d] = qu.front();
            qu.pop();

            if (curr == n - 1) return d;

            if (curr - 1 >= 0 && !visited_indices[curr - 1]) {
                visited_indices[curr - 1] = true;
                qu.push({curr - 1, d + 1});
            }
            if (curr + 1 < n && !visited_indices[curr + 1]) {
                visited_indices[curr + 1] = true;
                qu.push({curr + 1, d + 1});
            }

            for (int p : get_primes(nums[curr])) {
                if (visited_primes.insert(p).second) {
                    for (int nxt : prime_to_indices[p]) {
                        if (!visited_indices[nxt]) {
                            visited_indices[nxt] = true;
                            qu.push({nxt, d + 1});
                        }
                    }
                }
            }
        }

        return -1;
    }
};

import java.util.*;

class Solution {
    public int minJumps(int[] nums) {
        int n = nums.length;
        if (n <= 1) return 0;

        int maxVal = 0;
        for (int x : nums) if (x > maxVal) maxVal = x;

        int[] spf = new int[maxVal + 1];
        for (int i = 0; i <= maxVal; i++) spf[i] = i;
        for (int i = 2; i * i <= maxVal; i++) {
            if (spf[i] == i) {
                for (int j = i * i; j <= maxVal; j += i) {
                    if (spf[j] == j) spf[j] = i;
                }
            }
        }

        Map<Integer, List<Integer>> primeToIndices = new HashMap<>();
        for (int i = 0; i < n; i++) {
            for (int p : getPrimes(nums[i], spf)) {
                primeToIndices.computeIfAbsent(p, k -> new ArrayList<>()).add(i);
            }
        }

        boolean[] visitedIndices = new boolean[n];
        Set<Integer> visitedPrimes = new HashSet<>();
        Queue<int[]> queue = new ArrayDeque<>();

        visitedIndices[0] = true;
        queue.add(new int[]{0, 0});

        while (!queue.isEmpty()) {
            int[] cell = queue.poll();
            int curr = cell[0], d = cell[1];

            if (curr == n - 1) return d;

            if (curr - 1 >= 0 && !visitedIndices[curr - 1]) {
                visitedIndices[curr - 1] = true;
                queue.add(new int[]{curr - 1, d + 1});
            }
            if (curr + 1 < n && !visitedIndices[curr + 1]) {
                visitedIndices[curr + 1] = true;
                queue.add(new int[]{curr + 1, d + 1});
            }

            for (int p : getPrimes(nums[curr], spf)) {
                if (visitedPrimes.add(p)) {
                    List<Integer> list = primeToIndices.get(p);
                    if (list != null) {
                        for (int nxt : list) {
                            if (!visitedIndices[nxt]) {
                                visitedIndices[nxt] = true;
                                queue.add(new int[]{nxt, d + 1});
                            }
                        }
                    }
                }
            }
        }

        return -1;
    }

    private List<Integer> getPrimes(int x, int[] spf) {
        List<Integer> res = new ArrayList<>();
        while (x > 1) {
            int p = spf[x];
            res.add(p);
            while (x % p == 0) x /= p;
        }
        return res;
    }
}

