var minJumps = function(nums) {
    const n = nums.length;
    if (n <= 1) return 0;

    let maxVal = 0;
    for (const x of nums) if (x > maxVal) maxVal = x;

    const spf = new Int32Array(maxVal + 1);
    for (let i = 0; i <= maxVal; i++) spf[i] = i;
    for (let i = 2; i * i <= maxVal; i++) {
        if (spf[i] === i) {
            for (let j = i * i; j <= maxVal; j += i) {
                if (spf[j] === j) spf[j] = i;
            }
        }
    }

    const getPrimes = (x) => {
        const res = [];
        while (x > 1) {
            const p = spf[x];
            res.push(p);
            while (x % p === 0) x = Math.floor(x / p);
        }
        return res;
    };

    const primeToIndices = new Map();
    for (let i = 0; i < n; i++) {
        for (const p of getPrimes(nums[i])) {
            if (!primeToIndices.has(p)) primeToIndices.set(p, []);
            primeToIndices.get(p).push(i);
        }
    }

    const visitedIndices = new Uint8Array(n);
    const visitedPrimes = new Set();
    const queue = [[0, 0]];
    visitedIndices[0] = 1;

    let head = 0;
    while (head < queue.length) {
        const [curr, d] = queue[head++];
        if (curr === n - 1) return d;

        if (curr - 1 >= 0 && !visitedIndices[curr - 1]) {
            visitedIndices[curr - 1] = 1;
            queue.push([curr - 1, d + 1]);
        }
        if (curr + 1 < n && !visitedIndices[curr + 1]) {
            visitedIndices[curr + 1] = 1;
            queue.push([curr + 1, d + 1]);
        }

        for (const p of getPrimes(nums[curr])) {
            if (!visitedPrimes.has(p)) {
                visitedPrimes.add(p);
                const list = primeToIndices.get(p);
                if (list) {
                    for (const nxt of list) {
                        if (!visitedIndices[nxt]) {
                            visitedIndices[nxt] = 1;
                            queue.push([nxt, d + 1]);
                        }
                    }
                }
            }
        }
    }

    return -1;
};
